// The licenses of what the app ships, which the About page shows: two files of the build, which the scripts write
// with `Entries`.
import * as Arr from 'effect/Array'
import * as Effect from 'effect/Effect'
import * as Opt from 'effect/Option'
import * as Schema from 'effect/Schema'
// Generated by `bun run update-android-licenses`: the Android libraries, and what the native libraries compile in.
import androidLicenses from './licenses.android.generated.json' with { type: 'json' }
// Generated by `bun run update-licenses`: the packages of the JavaScript bundle.
import npmLicenses from './licenses.npm.generated.json' with { type: 'json' }

export type License = Readonly<{
  packageName: string
  licenses: Opt.Option<string>
  repository: Opt.Option<string>
  publisher: Opt.Option<string>
  email: Opt.Option<string>
  copyright: Opt.Option<string>
  name: Opt.Option<string>
  description: Opt.Option<string>
}>

/** What the About page shows of each package: the shape of both files. */
export const Entries = Schema.Record(
  Schema.String,
  Schema.Struct({
    licenses: Schema.optional(Schema.String),
    repository: Schema.optional(Schema.String),
    publisher: Schema.optional(Schema.String),
    email: Schema.optional(Schema.String),
    copyright: Schema.optional(Schema.String),
    name: Schema.optional(Schema.String),
    description: Schema.optional(Schema.String),
  }),
)

/**
 * Every license, the JavaScript's packages first, then Android's. A file that does not decode is a bug of the
 * build.
 */
export const all: Effect.Effect<ReadonlyArray<License>> = Schema.decodeEffect(Entries)({
  ...npmLicenses,
  ...androidLicenses,
}).pipe(
  Effect.orDie,
  Effect.map((entries) =>
    Arr.map(Object.entries(entries), ([packageName, entry]): License => ({
      packageName,
      licenses: Opt.fromNullishOr(entry.licenses),
      repository: Opt.fromNullishOr(entry.repository),
      publisher: Opt.fromNullishOr(entry.publisher),
      email: Opt.fromNullishOr(entry.email),
      copyright: Opt.fromNullishOr(entry.copyright),
      name: Opt.fromNullishOr(entry.name),
      description: Opt.fromNullishOr(entry.description),
    }))
  ),
)
